begin;
select plan(26);
insert into auth.users(id) values('66666666-6666-4666-8666-666666666661'),('66666666-6666-4666-8666-666666666662');
select append_learning_events('66666666-6666-4666-8666-666666666661','[{"kind":"card-review","id":"first"},{"kind":"card-review","id":"second"}]');
update learning_events set received_at='2020-01-01T00:00:00Z' where user_id='66666666-6666-4666-8666-666666666661';
select is(retain_learning_event('66666666-6666-4666-8666-666666666661','first',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),'{"kind":"retained","sourceKind":"practice","id":"first","finishedAt":0}'),false,'Raw details cannot expire before memory projection');
create temp table review_fixture as select '{"due":0,"stability":0,"difficulty":0,"elapsed_days":0,"scheduled_days":0,"learning_steps":0,"reps":0,"lapses":0,"state":0}'::jsonb card;
select is(jsonb_array_length(review_pending('66666666-6666-4666-8666-666666666661',50)),2,'New canonical events queue for review projection');
select throws_ok('select review_pending(null,51)','P0001','Invalid review page','Bounded pages');
select is(commit_review_period('66666666-6666-4666-8666-666666666661','second',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='second'),0,'{"skills":{},"cards":{}}'),'conflict','Later evidence cannot overtake earlier evidence');
select throws_ok($$select commit_review_period('66666666-6666-4666-8666-666666666661','first','wrong',0,'{"skills":{},"cards":{}}')$$,'P0001','Review source conflict','Hash mismatch rejected');
select is(commit_review_period('66666666-6666-4666-8666-666666666661','first',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),9,'{"skills":{},"cards":{}}'),'conflict','Stale account revision rejected');
select throws_ok($$select commit_review_period('66666666-6666-4666-8666-666666666661','first',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),0,'{"skills":{"test":{"due":0}},"cards":{}}')$$,'P0001','Invalid review skill','Partial state rejected atomically');
select is((select count(*)::integer from skill_progress where user_id='66666666-6666-4666-8666-666666666661'),0,'Invalid projection did not create skills');
select is(commit_review_period('66666666-6666-4666-8666-666666666661','first',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),0,(select jsonb_build_object('skills',jsonb_build_object('test.skill',card),'cards',jsonb_build_object('test.card@1',card)) from review_fixture)),'applied','Skill and card schedules commit together');
select is((select fsrs_version from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),1,'Receipt committed with schedules');
select is(commit_review_period('66666666-6666-4666-8666-666666666661','first',(select event_hash from learning_events where user_id='66666666-6666-4666-8666-666666666661' and client_id='first'),0,'{"skills":{},"cards":{}}'),'already','Retry cannot advance memory twice');
select is((select revision from review_control where user_id='66666666-6666-4666-8666-666666666661'),1::bigint,'Revision advances once');
select is((rating_snapshot('66666666-6666-4666-8666-666666666661','[]')->'skills')::text,'{}','Assisted-only memory does not invent a Glicko rating');
select is(review_card_valid((select card||'{"state":9}'::jsonb from review_fixture)),false,'Unknown states rejected');
select is(review_card_valid((select card||'{"extra":0}'::jsonb from review_fixture)),false,'Unknown fields rejected');
set local role anon;
select throws_ok('select learner_review_snapshot()','42501',null,'Anonymous snapshot denied');
select throws_ok('select * from card_review_progress','42501',null,'Anonymous schedules denied');
set local role authenticated;
set local request.jwt.claims='{"sub":"66666666-6666-4666-8666-666666666661","role":"authenticated"}';
select throws_ok('select learner_review_snapshot()','P0001','Review projection pending','Incomplete own snapshot cannot be cached');
select is((select count(*)::integer from card_review_progress),1,'Owner sees own cards');
select throws_ok('update card_review_progress set fsrs=''{}''','42501',null,'Client cannot forge schedules');
select throws_ok('select review_snapshot(null)','42501',null,'Internal snapshots service only');
select throws_ok('select commit_review_period(null,''x'',''x'',0,''{}'')','42501',null,'Projection writes service only');
set local request.jwt.claims='{"sub":"66666666-6666-4666-8666-666666666662","role":"authenticated"}';
select is((select count(*)::integer from card_review_progress),0,'Other owner sees no cards');
select is((learner_review_snapshot()->>'throughSequence')::bigint,0::bigint,'Other account cursor independent');
reset role;
delete from auth.users where id='66666666-6666-4666-8666-666666666661';
select is((select count(*)::integer from card_review_progress where user_id='66666666-6666-4666-8666-666666666661'),0,'Deletion cascades to card schedules');
select is((select count(*)::integer from review_control where user_id='66666666-6666-4666-8666-666666666661'),0,'Deletion cascades to projection control');
select * from finish();
rollback;
